"""Exact arithmetic in the free associative algebra over Q generated by letters (A, B, ...).

An element is a dict mapping words (str) to Fractions.  Every Lie polynomial is an
element of this algebra, so any identity between commutators can be checked by
expanding both sides into words.  This replaces FeynCalc's DotSimplify/Commutator.
"""
from collections import defaultdict
from fractions import Fraction

ONE = {'': Fraction(1)}


def letter(x):
    return {x: Fraction(1)}


def add(p, q, c=1):
    """p + c*q"""
    r = dict(p)
    for w, v in q.items():
        s = r.get(w, 0) + c * v
        if s:
            r[w] = s
        else:
            r.pop(w, None)
    return r


def scale(p, c):
    if c == 0:
        return {}
    return {w: c * v for w, v in p.items()}


def mul(p, q, maxdeg=None):
    r = defaultdict(Fraction)
    for w1, v1 in p.items():
        for w2, v2 in q.items():
            if maxdeg is not None and len(w1) + len(w2) > maxdeg:
                continue
            r[w1 + w2] += v1 * v2
    return {w: v for w, v in r.items() if v}


def comm(p, q):
    """[p, q] = pq - qp"""
    return add(mul(p, q), mul(q, p), -1)


def right_nested(elems):
    """[e_1, [e_2, ..., [e_{n-1}, e_n]...]] for a list of algebra elements."""
    r = elems[-1]
    for e in reversed(elems[:-1]):
        r = comm(e, r)
        if not r:
            return {}
    return r


def right_nested_word(word):
    """Right-nested commutator of the letters of `word`, e.g. 'AAB' -> [A,[A,B]]."""
    return right_nested([letter(x) for x in word])


def homogeneous(p, d):
    return {w: v for w, v in p.items() if len(w) == d}


def exp_series(p, maxdeg):
    """exp(p) truncated at word length maxdeg (p must have no constant term)."""
    res = dict(ONE)
    term = dict(ONE)
    for n in range(1, maxdeg + 1):
        term = scale(mul(term, p, maxdeg), Fraction(1, n))
        if not term:
            break
        res = add(res, term)
    return res


def log_series(z, maxdeg):
    """log(z) truncated at word length maxdeg (z must have constant term 1)."""
    y = add(z, ONE, -1)
    res = {}
    power = dict(ONE)
    for k in range(1, maxdeg + 1):
        power = mul(power, y, maxdeg)
        if not power:
            break
        res = add(res, power, Fraction((-1) ** (k + 1), k))
    return res


def bch_product(factors, maxdeg):
    """log( exp(c_1 X_1) exp(c_2 X_2) ... ) truncated at word length maxdeg.

    factors: list of (algebra element, coefficient), e.g. [(letter('A'), 1/2), ...]
    """
    z = dict(ONE)
    for elem, c in factors:
        z = mul(z, exp_series(scale(elem, Fraction(c)), maxdeg), maxdeg)
    return log_series(z, maxdeg)
